@startuml
abstract class Value {
  #attribute : String
  get_name()
  accept(parameter : Visitor)
}
class Null {
  accept(parameter : Visitor)
}
class String {
  -data : String
  get_data() : String
  accept(parameter : Visitor)
}
class Bool {
  -data : Boolean
  get_data() : Boolean
  accept(parameter : Visitor)
}
class Number {
  -data : Long
  get_data() : Long
  accept(parameter : Visitor)
}
class Array {
  -data : Value
  get_data() : Value
  accept(parameter : Visitor)
}
class Visitor {
  visit(parameter : Array)
  visit(parameter : Bool)
  visit(parameter : Null)
  visit(parameter : Number)
  visit(parameter : String)
}
class Json {
  -values : Value
  add_value(parameter : Value)
  get_values() : Value
  write_file()
  accept(parameter : Visitor)
}
class Documents {
  -file
  -data : Json
  -file_name : String
  -tab_counter : Integer
  write_file()
  write_object(parameter : Json)
  write_array(parameter : Array)
  write_string(parameter : String)
  write_bool(parameter : Bool)
  write_null(parameter : Null)
  write_number(parameter : Number)
  write_value(parameter : Value)
  tab()
}
class Print
class ArrPrint
class NamedCapabilityMetadata
class NamedCapabilityMetadata2 {
  name : String
}
Value <|-- Null
Value <|-- String
Value <|-- Bool
Value <|-- Number
Value <|-- Array
Value <|-- Json
Visitor <|-- Print
Visitor <|-- ArrPrint
@enduml

